"48 700 ≈ 50 000, 31 200 ≈ 30 000. Сумма примерно 80 000. Точный ответ: 79 900.": "48 700 ≈ 50 000, 31 200 ≈ 30 000. The sum is about 80 000. The exact answer: 79 900.",
