"V = 8 · 4 · 4 = 128 дм³. 1 дм³ вмещает 1 л воды, значит в аквариум входит 128 л": "V = 8 · 4 · 4 = 128 dm³. 1 dm³ holds 1 l of water, so the aquarium holds 128 l",
"Пересечение двух множеств всегда содержит больше элементов, чем их объединение.": "The intersection of two sets always has more elements than their union.",
