"Уменьшаемое − вычитаемое = разность. Значит, уменьшаемое = разность + вычитаемое.": "Minuend − subtrahend = difference. So minuend = difference + subtrahend.",
"Проверим умножением: 8 281 · 7 = 57 967. В остальных равенствах частное неверное.": "Let us check by multiplication: 8 281 · 7 = 57 967. In the other equalities the quotient is wrong.",
