"в записи произведения 4 цифры: 1 234 · 3 = 3 702; 2 500 · 3 = 7 500": "the product has 4 digits: 1 234 · 3 = 3 702; 2 500 · 3 = 7 500",
"в записи произведения 4 цифры: 1 234 · 3 = 3 702; 2 500 · 3 = 7 500": "the product has 4 digits: 1 234 · 3 = 3 702; 2 500 · 3 = 7 500",
