"Остаток меньше делителя, поэтому наибольший остаток 1 000 − 1 = 999.": "The remainder is less than the divisor, so the greatest remainder is 1 000 − 1 = 999.",
"Остаток меньше делителя, поэтому наибольший остаток 1 000 − 1 = 999.": "The remainder is less than the divisor, so the greatest remainder is 1 000 − 1 = 999.",
"Из 15 танцоров 4 ходят ещё и рисовать. Сколько ребят только танцуют?": "Of 15 dancers, 4 also go to drawing. How many children only dance?",
