"В одном слое 9 · 4 = 36 кубиков. Слоёв 6. Всего 36 · 6 = 216 кубиков.": "In one layer there are 9 · 4 = 36 cubes. There are 6 layers. In total 36 · 6 = 216 cubes.",
"Если в числах поровну цифр, их сравнивают, начиная с младшего разряда.": "If the numbers have the same number of digits, they are compared starting from the lowest place.",
