"в сумме неизвестно слагаемое: надо из суммы вычесть известное слагаемое": "in a sum an addend is unknown: subtract the known addend from the sum",
"умножаем сумму: (a + b) · c = a · c + b · c — умножаем каждое слагаемое": "we multiply a sum: (a + b) · c = a · c + b · c — we multiply each addend",
