"A = { 1; 3; 7; 9; 11 }, B = { 1; 3; 4; 5; 12 }. Найди пересечение A ∩ B.": "A = { 1; 3; 7; 9; 11 }, B = { 1; 3; 4; 5; 12 }. Find the intersection A ∩ B.",
"Длина ленты 28 845 см. Сколько целых метров в этой ленте? (1 м = 100 см)": "The length of a ribbon is 28 845 cm. How many whole metres are in this ribbon? (1 m = 100 cm)",
"Длина ленты 28 845 см. Сколько целых метров в этой ленте? (1 м = 100 см)": "The length of a ribbon is 28 845 cm. How many whole metres are in this ribbon? (1 m = 100 cm)",
"Крупных единиц получается меньше, поэтому делим. Например, 7 000 мг = 7 г": "There are fewer large units, so we divide. For example, 7 000 mg = 7 g",
"Лыжник идёт со скоростью 80 м/мин. Какое расстояние он пройдёт за 25 мин?": "A skier goes at a speed of 80 m/min. What distance will he cover in 25 min?",
"Нет разряда — считаем в нём 0. Разряды при этом остаются на своих местах.": "If there is no place, we count 0 in it. The places stay in their positions.",
"Площадь фигуры из двух прямоугольников 7 м × 3 м и 6 м × 5 м равна 51 м².": "The area of a shape made of two rectangles 7 m × 3 m and 6 m × 5 m is 51 m².",
"Площадь фигуры из двух прямоугольников 7 м × 3 м и 6 м × 5 м равна 51 м².": "The area of a shape made of two rectangles 7 m × 3 m and 6 m × 5 m is 51 m².",
"Посчитай, сколько цифр отделяют справа: столько, сколько нулей у делителя.": "Count how many digits to separate on the right: as many as there are zeros in the divisor.",
"Если единицу делаем мельче, число умножаем. 4 дм³ = 4 · 1 000 = 4 000 см³.": "If we make the unit smaller, we multiply the number. 4 dm³ = 4 · 1 000 = 4 000 cm³.",
"Если единицу делаем мельче, число умножаем. 4 дм³ = 4 · 1 000 = 4 000 см³.": "If we make the unit smaller, we multiply the number. 4 dm³ = 4 · 1 000 = 4 000 cm³.",
